from src.nodes.base import BaseNode
from src.runtime.lighting import get_lighting_review
import json

class Hou_Mcp_Lighting_Review(BaseNode):
    name = "hou_mcp_lighting_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("plan_json", "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("review_json",      "string")
        self.add_output("score",            "float")
        self.add_output("grade",            "string")
        self.add_output("production_ready", "bool")

    async def execute(self, inputs):
        plan_json = str(inputs.get("plan_json", "") or "")
        try:
            plan_dict = json.loads(plan_json) if plan_json.strip() else {}
        except Exception as exc:
            self.log_error(f"Failed to parse plan_json: {exc}")
            return {"review_json": "{}", "score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}
        try:
            engine = get_lighting_review()
            result = engine.review_plan(plan_dict)
            self.log_info(
                f"Lighting review: grade={result.grade}, score={result.score:.2f}, "
                f"production_ready={result.production_ready}. Findings: {len(result.findings)}."
            )
            return {
                "review_json":      json.dumps(result.to_dict(), sort_keys=True, default=str),
                "score":            result.score,
                "grade":            result.grade,
                "production_ready": result.production_ready,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Lighting review failed: {exc}")
            return {"review_json": "{}", "score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Lighting_Review
